import hashlib,pathlib,sqlite3

def triage_rpmdb(database,payload_root,manifest_paths):
    database=pathlib.Path(database);root=pathlib.Path(payload_root).resolve()
    if not database.is_file() or database.is_symlink():raise ValueError("database must be an existing regular file")
    if not isinstance(manifest_paths,list) or any(not isinstance(x,str) or not x for x in manifest_paths):
        raise ValueError("manifest paths must be nonempty strings")
    present=[];missing=[]
    for raw in manifest_paths:
        candidate=(root/raw).resolve()
        if not candidate.is_relative_to(root):raise ValueError("payload path escapes root")
        (present if candidate.is_file() else missing).append(raw)
    before=hashlib.sha256(database.read_bytes()).hexdigest();magic=database.read_bytes()[:16]
    if magic==b"SQLite format 3\x00":
        backend="sqlite";integrity="ok"
        uri=database.resolve().as_uri()+"?mode=ro&immutable=1"
        try:
            with sqlite3.connect(uri,uri=True,timeout=2) as conn:
                rows=conn.execute("PRAGMA quick_check").fetchall()
                if rows!=[("ok",)]:integrity="corrupt"
        except sqlite3.DatabaseError:integrity="corrupt"
    else:
        backend="unknown";integrity="not_checked"
    after=hashlib.sha256(database.read_bytes()).hexdigest()
    if before!=after:raise RuntimeError("read-only inspection changed database bytes")
    if integrity=="ok":status="database_integrity_ok"
    elif integrity=="corrupt":status="database_corrupt_preserved"
    else:status="backend_requires_vendor_specific_inspection"
    return {"backend":backend,"integrity":integrity,"status":status,"database_sha256":after,
        "payload_present":sorted(present),"payload_missing":sorted(missing),"database_unchanged":True,
        "next":"stop concurrent package transactions; preserve database, logs and storage evidence; use this RPM version's vendor procedure; reconcile installed packages against trusted manifests and file verification; never delete the database blindly"}
